    //Sun
    [System.Serializable]
    public class LightingSunOverride : BlockOverride
    {
        public override string Title => "Sun";
        public override string Category => "Lighting";
        public override bool FeatureEnabledGlobally => CozyPreferences.CurrentStyle.UseLightingSun;
        public override void ToggleFeature() => CozyPreferences.CurrentStyle.ToggleLightingSun();

        /// <summary>
        /// Sets the color of the sun light at a certain time. Starts and ends at midnight.
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the color of the sun light at a certain time. Starts and ends at midnight.")]
        [BlockProperty(VarType.Color, "LightColor")]
        public BlockColorValue lightColor = new BlockColorValue(default);
        /// <summary>
        /// Sets the intensity of the sun light at a certain time. Starts and ends at midnight.
        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the intensity of the sun light at a certain time. Starts and ends at midnight.")]
        [BlockProperty(VarType.Float, "LightIntensity")]
        public BlockFloatValue lightIntensity = new BlockFloatValue(default);
        /// <summary>
        /// Set the intensity of the sun light shadows
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the intensity of the sun light shadows")]
        [BlockProperty(VarType.Float, "ShadowIntensity", minFloat = 0, maxFloat = 1)]
        public BlockFloatValue shadowIntensity = new BlockFloatValue(default);

        public override bool CaptureFromParameters(AtmosphereParameters parameters) {
            lightColor = new BlockColorValue(parameters.lightingSunLightColor);
            lightIntensity = new BlockFloatValue(parameters.lightingSunLightIntensity);
            shadowIntensity = new BlockFloatValue(parameters.lightingSunShadowIntensity);
            return true;
        }

        public override void ApplyToWeatherSphere(AtmosphereParameters parameters, float weight) {
            if (!active || !FeatureEnabledGlobally) return;
            if (!lightColor.disabled)
                parameters.lightingSunLightColor.Lerp(lightColor.value, weight);
            if (!lightIntensity.disabled)
                parameters.lightingSunLightIntensity.Lerp(lightIntensity.value, weight);
            if (!shadowIntensity.disabled)
                parameters.lightingSunShadowIntensity.Lerp(shadowIntensity.value, weight);
        }
    }

